```c
static uint8_t s_dmaBuf[UART_RX_BUF_SIZE];

void UART_VOFA_Init(void)
{
    s_uartQueue = xQueueCreate(UART_QUEUE_LENGTH, sizeof(UartRxPacket_t));
    configASSERT(s_uartQueue);
    __HAL_UART_ENABLE_IT(&huart1, UART_IT_IDLE);
    HAL_UART_Receive_DMA(&huart1, s_dmaBuf, UART_RX_BUF_SIZE);
}

void UART_RxIdleCallback(UART_HandleTypeDef *huart)
{
    BaseType_t hpw = pdFALSE;
    if (huart->Instance != USART1) return;
    if (__HAL_UART_GET_FLAG(huart, UART_FLAG_IDLE) == RESET) return;
    __HAL_UART_CLEAR_IDLEFLAG(huart);

    HAL_UART_DMAStop(huart);
    uint16_t len = UART_RX_BUF_SIZE - __HAL_DMA_GET_COUNTER(huart->hdmarx);

    UartRxPacket_t pkt;
    pkt.len = (len > UART_RX_BUF_SIZE) ? UART_RX_BUF_SIZE : len;
    memcpy(pkt.buf, s_dmaBuf, pkt.len);
    if (s_uartQueue) xQueueSendFromISR(s_uartQueue, &pkt, &hpw);

    HAL_UART_Receive_DMA(huart, s_dmaBuf, UART_RX_BUF_SIZE);
    portYIELD_FROM_ISR(hpw);
}
```
Note: mutating pkt on stack in ISR is fine (queue copies). Careful: 128-byte struct copy in ISR — acceptable.

