uint8_t MPU_DMP_Init(void)
{
    int result;
    SoftI2C_Init();
    result = mpu_init(NULL);
    if (result) return 1;
    if (mpu_set_sensors(INV_XYZ_GYRO | INV_XYZ_ACCEL)) return 2;
    if (mpu_configure_fifo(INV_XYZ_GYRO | INV_XYZ_ACCEL)) return 3;
    if (mpu_set_sample_rate(DEFAULT_MPU_HZ)) return 4;
    if (dmp_load_motion_driver_firmware()) return 5;
    if (dmp_set_orientation(inv_orientation_matrix_to_scalar(gyro_orientation))) return 6;
    if (dmp_enable_feature(DMP_FEATURE_6X_LP_QUAT | DMP_FEATURE_TAP |
        DMP_FEATURE_ANDROID_ORIENT | DMP_FEATURE_SEND_RAW_ACCEL | DMP_FEATURE_SEND_CAL_GYRO |
        DMP_FEATURE_GYRO_CAL)) return 7;
    if (dmp_set_fifo_rate(DEFAULT_MPU_HZ)) return 8;
    /* run_self_test(); 可选 */
    if (mpu_set_dmp_state(1)) return 9;
    return 0;
}

uint8_t MPU_DMP_GetAngles(float *pitch, float *roll, float *yaw)
{
    float q0=1.0f,q1=0,q2=0,q3=0;
    short gyro[3], accel[3], sensors;
    unsigned long sensor_timestamp;
    unsigned char more;
    long quat[4];
    if (dmp_read_fifo(gyro, accel, quat, &sensor_timestamp, &sensors, &more)) return 1;
    if (sensors & INV_WXYZ_QUAT) {
        q0 = quat[0]/q30; q1 = quat[1]/q30; q2 = quat[2]/q30; q3 = quat[3]/q30;
        *pitch = asinf(-2*q1*q3 + 2*q0*q2) * 57.2957795f;
        *roll  = atan2f(2*q2*q3 + 2*q0*q1, -2*q1*q1 - 2*q2*q2 + 1) * 57.2957795f;
        *yaw   = atan2f(2*(q1*q2 + q0*q3), q0*q0 + q1*q1 - q2*q2 - q3*q3) * 57.2957795f;
        return 0;
    }
    return 2;
}
