#define BREATH_TICK_HZ 1000
static volatile uint16_t s_periodMs = 2000;  /* 一个完整呼吸周期 */
static volatile uint32_t s_tick = 0;
static volatile uint8_t  s_enable = 1;

void BreathLED_TickISR(void)
{
    if (!s_enable) return;
    uint32_t period = s_periodMs;
    if (period == 0) { __HAL_TIM_SET_COMPARE(...); return; }
    s_tick++;
    if (s_tick >= period) s_tick = 0;
    /* 三角波 -> 正弦更柔和: 用查表或 sinf */
    float phase = 2.0f * 3.1415926f * (float)s_tick / (float)period;
    float duty = 0.5f - 0.5f * cosf(phase); // 0..1，余弦呼吸
    uint32_t ccr = (uint32_t)(duty * (float)(htim3.Init.Period));
    __HAL_TIM_SET_COMPARE(BREATH_PWM_TIM, BREATH_PWM_CHANNEL, ccr);
}
```
Using cosf in ISR each 1ms; acceptable but 1kHz float is fine on F4 with FPU. Alternatively table.

