/* ------------------------------------------------------------------
 * 引脚电平宏：开漏输出 + 外部/内部上拉
 *   输出 0 -> 拉低总线；输出 1 -> 释放总线，由上拉电阻拉高
 * ------------------------------------------------------------------*/
#define SCL_H()  HAL_GPIO_WritePin(SOFT_I2C_SCL_PORT, SOFT_I2C_SCL_PIN, GPIO_PIN_SET)
#define SCL_L()  HAL_GPIO_WritePin(SOFT_I2C_SCL_PORT, SOFT_I2C_SCL_PIN, GPIO_PIN_RESET)
#define SDA_H()  HAL_GPIO_WritePin(SOFT_I2C_SDA_PORT, SOFT_I2C_SDA_PIN, GPIO_PIN_SET)
#define SDA_L()  HAL_GPIO_WritePin(SOFT_I2C_SDA_PORT, SOFT_I2C_SDA_PIN, GPIO_PIN_RESET)
#define SDA_R()  HAL_GPIO_ReadPin(SOFT_I2C_SDA_PORT, SOFT_I2C_SDA_PIN)

void SoftI2C_DelayUs(uint32_t us)
{
    uint32_t start  = DWT->CYCCNT;
    uint32_t cycles = us * (SystemCoreClock / 1000000UL);

    while ((DWT->CYCCNT - start) < cycles)
    {
        __NOP();
    }
}

static void SoftI2C_DelayHalfPeriod(void)
{
    /* 100 kHz -> 半周期 5 us；400 kHz -> 1.25 us */
    SoftI2C_DelayUs(1000UL / (SOFT_I2C_SPEED_KHZ * 2UL) > 0 ?
                    1000UL / (SOFT_I2C_SPEED_KHZ * 2UL) : 1UL);
}

void SoftI2C_Init(void)
{
    GPIO_InitTypeDef gpio;

    /* 使能 DWT 周期计数器，用于精确延时 */
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    DWT->CYCCNT = 0UL;
    DWT->CTRL  |= DWT_CTRL_CYCCNTENA_Msk;

    SOFT_I2C_SCL_CLK_EN();
    SOFT_I2C_SDA_CLK_EN();

    gpio.Mode  = GPIO_MODE_OUTPUT_OD;     /* 开漏 */
    gpio.Pull  = GPIO_PULLUP;             /* 开上拉（外部已有 4.7k 时也可 NOPULL） */
    gpio.Speed = GPIO_SPEED_FREQ_HIGH;

    gpio.Pin = SOFT_I2C_SCL_PIN;
    HAL_GPIO_Init(SOFT_I2C_SCL_PORT, &gpio);

    gpio.Pin = SOFT_I2C_SDA_PIN;
    HAL_GPIO_Init(SOFT_I2C_SDA_PORT, &gpio);

    SCL_H();
    SDA_H();
    SoftI2C_DelayUs(10);
}

/* 起始条件：SCL 高电平时 SDA 由高变低 */
void SoftI2C_Start(void)
{
    SDA_H();
    SCL_H();
    SoftI2C_DelayHalfPeriod();
    SDA_L();
    SoftI2C_DelayHalfPeriod();
    SCL_L();
}

/* 停止条件：SCL 高电平时 SDA 由低变高 */
void SoftI2C_Stop(void)
{
    SCL_L();
    SDA_L();
    SoftI2C_DelayHalfPeriod();
    SCL_H();
    SoftI2C_DelayHalfPeriod();
    SDA_H();
    SoftI2C_DelayHalfPeriod();
}

/* 发送 1 字节（高位在前），SCL 上升沿锁存 */
void SoftI2C_SendByte(uint8_t byte)
{
    for (uint8_t i = 0; i < 8; i++)
    {
        SCL_L();
        if (byte & 0x80)
        {
            SDA_H();
        }
        else
        {
            SDA_L();
        }
        byte <<= 1;
        SoftI2C_DelayHalfPeriod();
        SCL_H();
        SoftI2C_DelayHalfPeriod();
    }
    SCL_L();
}

/* 读取 1 字节，ack=1 表示读完继续（发 ACK），ack=0 表示最后一字节（发 NACK） */
uint8_t SoftI2C_ReadByte(uint8_t ack)
{
    uint8_t value = 0;

    SDA_H();                      /* 释放 SDA，交给从机 */
    for (uint8_t i = 0; i < 8; i++)
    {
        SCL_L();
        SoftI2C_DelayHalfPeriod();
        SCL_H();
        value <<= 1;
        if (SDA_R() == GPIO_PIN_SET)
        {
            value |= 0x01;
        }
        SoftI2C_DelayHalfPeriod();
    }
    SCL_L();

    SoftI2C_SendAck(ack);
    return value;
}

/* 等待从机应答：0 = 收到 ACK，1 = NACK（失败） */
uint8_t SoftI2C_WaitAck(void)
{
    uint8_t errTime = 0;

    SDA_H();
    SoftI2C_DelayHalfPeriod();
    SCL_H();
    SoftI2C_DelayHalfPeriod();

    while (SDA_R() == GPIO_PIN_SET)
    {
        if (++errTime > 250)
        {
            SoftI2C_Stop();
            return 1;
        }
    }

    SCL_L();
    return 0;
}

/* 主机应答：ack=0 -> 拉低 SDA(ACK)，ack=1 -> 释放 SDA(NACK) */
void SoftI2C_SendAck(uint8_t ack)
{
    SCL_L();
    if (ack)
    {
        SDA_H();
    }
    else
    {
        SDA_L();
    }
    SoftI2C_DelayHalfPeriod();
    SCL_H();
    SoftI2C_DelayHalfPeriod();
    SCL_L();
    SDA_H();
}

/* ------------------------- 组合读写接口 ------------------------- */

uint8_t SoftI2C_WriteReg(uint8_t devAddr, uint8_t regAddr, uint8_t data)
{
    SoftI2C_Start();
    SoftI2C_SendByte((devAddr << 1) | 0x00);
    if (SoftI2C_WaitAck())
    {
        SoftI2C_Stop();
        return 1;
    }
    SoftI2C_SendByte(regAddr);
    if (SoftI2C_WaitAck())
    {
        SoftI2C_Stop();
        return 1;
    }
    SoftI2C_SendByte(data);
    if (SoftI2C_WaitAck())
    {
        SoftI2C_Stop();
        return 1;
    }
    SoftI2C_Stop();
    return 0;
}

uint8_t SoftI2C_ReadReg(uint8_t devAddr, uint8_t regAddr, uint8_t *data)
{
    SoftI2C_Start();
    SoftI2C_SendByte((devAddr << 1) | 0x00);
    if (SoftI2C_WaitAck())
    {
        SoftI2C_Stop();
        return 1;
    }
    SoftI2C_SendByte(regAddr);
    if (SoftI2C_WaitAck())
    {
        SoftI2C_Stop();
        return 1;
    }

    SoftI2C_Start();                      /* 重复起始条件 */
    SoftI2C_SendByte((devAddr << 1) | 0x01);
    if (SoftI2C_WaitAck())
    {
        SoftI2C_Stop();
        return 1;
    }
    *data = SoftI2C_ReadByte(1);          /* 最后一字节发 NACK */
    SoftI2C_Stop();
    return 0;
}

uint8_t SoftI2C_WriteBuffer(uint8_t devAddr, uint8_t regAddr, uint16_t len, uint8_t *buf)
{
    SoftI2C_Start();
    SoftI2C_SendByte((devAddr << 1) | 0x00);
    if (SoftI2C_WaitAck())
    {
        SoftI2C_Stop();
        return 1;
    }
    SoftI2C_SendByte(regAddr);
    if (SoftI2C_WaitAck())
    {
        SoftI2C_Stop();
        return 1;
    }
    for (uint16_t i = 0; i < len; i++)
    {
        SoftI2C_SendByte(buf[i]);
        if (SoftI2C_WaitAck())
        {
            SoftI2C_Stop();
            return 1;
        }
    }
    SoftI2C_Stop();
    return 0;
}

uint8_t SoftI2C_ReadBuffer(uint8_t devAddr, uint8_t regAddr, uint16_t len, uint8_t *buf)
{
    SoftI2C_Start();
    SoftI2C_SendByte((devAddr << 1) | 0x00);
    if (SoftI2C_WaitAck())
    {
        SoftI2C_Stop();
        return 1;
    }
    SoftI2C_SendByte(regAddr);
    if (SoftI2C_WaitAck())
    {
        SoftI2C_Stop();
        return 1;
    }

    SoftI2C_Start();
    SoftI2C_SendByte((devAddr << 1) | 0x01);
    if (SoftI2C_WaitAck())
