#include "soft_i2c.h"

/* 量程对应的灵敏度（LSB / 单位） */
#define ACCEL_SENS_2G      16384.0f
#define ACCEL_SENS_4G       8192.0f
#define ACCEL_SENS_8G       4096.0f
#define ACCEL_SENS_16G      2048.0f

#define GYRO_SENS_250        131.0f
#define GYRO_SENS_500         65.5f
#define GYRO_SENS_1000        32.8f
#define GYRO_SENS_2000        16.4f

static float s_accelSens = ACCEL_SENS_8G;
static float s_gyroSens  = GYRO_SENS_2000;

uint8_t MPU6050_WhoAmI(uint8_t *id)
{
    return SoftI2C_ReadReg(MPU6050_I2C_ADDR, MPU6050_RA_WHO_AM_I, id);
}

uint8_t MPU6050_Init(void)
{
    uint8_t id = 0;
    uint8_t res;

    SoftI2C_Init();
    SoftI2C_DelayUs(100000UL);            /* 等模块上电稳定 */

    /* 1) 复位 */
    res = SoftI2C_WriteReg(MPU6050_I2C_ADDR, MPU6050_RA_PWR_MGMT_1, 0x80);
    SoftI2C_DelayUs(100000UL);

    /* 2) 唤醒 + 选择内部 8 MHz 时钟 */
    res |= SoftI2C_WriteReg(MPU6050_I2C_ADDR, MPU6050_RA_PWR_MGMT_1, 0x00);
    res |= SoftI2C_WriteReg(MPU6050_I2C_ADDR, MPU6050_RA_PWR_MGMT_2, 0x00);

    /* 3) WHO_AM_I 自检，正常为 0x68 */
    res |= MPU6050_WhoAmI(&id);
    if ((res != 0) || ((id & 0x7E) != 0x68))
    {
        return 1;
    }

    /* 4) 采样分频：陀螺输出 1 kHz（DLPF 使能时），SMPLRT_DIV = 0 -> 1 kHz */
    res |= SoftI2C_WriteReg(MPU6050_I2C_ADDR, MPU6050_RA_SMPLRT_DIV, 0x00);

    /* 5) 低通滤波带宽：DLPF_CFG = 2 -> 加速度 94 Hz / 陀螺 98 Hz */
    res |= SoftI2C_WriteReg(MPU6050_I2C_ADDR, MPU6050_RA_CONFIG, 0x02);

    /* 6) 量程 */
    res |= SoftI2C_WriteReg(MPU6050_I2C_ADDR, MPU6050_RA_GYRO_CONFIG,  MPU6050_GYRO_RANGE);
    res |= SoftI2C_WriteReg(MPU6050_I2C_ADDR, MPU6050_RA_ACCEL_CONFIG, MPU6050_ACCEL_RANGE);

    /* 7) 关闭中断与 FIFO（DMP 初始化时会重新配置） */
    res |= SoftI2C_WriteReg(MPU6050_I2C_ADDR, MPU6050_RA_INT_ENABLE, 0x00);
    res |= SoftI2C_WriteReg(MPU6050_I2C_ADDR, MPU6050_RA_FIFO_EN,    0x00);
    res |= SoftI2C_WriteReg(MPU6050_I2C_ADDR, MPU6050_RA_INT_PIN_CFG, 0x80);

    switch (MPU6050_ACCEL_RANGE)
    {
        case MPU6050_ACCEL_FS_2G:  s_accelSens = ACCEL_SENS_2G;  break;
        case MPU6050_ACCEL_FS_4G:  s_accelSens = ACCEL_SENS_4G;  break;
        case MPU6050_ACCEL_FS_8G:  s_accelSens = ACCEL_SENS_8G;  break;
        case MPU6050_ACCEL_FS_16G: s_accelSens = ACCEL_SENS_16G; break;
        default: break;
    }
    switch (MPU6050_GYRO_RANGE)
    {
        case MPU6050_GYRO_FS_250:  s_gyroSens = GYRO_SENS_250;  break;
        case MPU6050_GYRO_FS_500:  s_gyroSens = GYRO_SENS_500;  break;
        case MPU6050_GYRO_FS_1000: s_gyroSens = GYRO_SENS_1000; break;
        case MPU6050_GYRO_FS_2000: s_gyroSens = GYRO_SENS_2000; break;
        default: break;
    }

    return res;
}

/* 读取三轴加速度 + 三轴陀螺仪原始数据（0x3B 起 14 字节连续读） */
uint8_t MPU6050_ReadRaw(MPU6050_RawData_t *raw)
{
    uint8_t buf[14];

    if (SoftI2C_ReadBuffer(MPU6050_I2C_ADDR, MPU6050_RA_ACCEL_XOUT_H, 14, buf) != 0)
    {
        return 1;
    }

    raw->accel[0] = (int16_t)(((uint16_t)buf[0]  << 8) | buf[1]);
    raw->accel[1] = (int16_t)(((uint16_t)buf[2]  << 8) | buf[3]);
    raw->accel[2] = (int16_t)(((uint16_t)buf[4]  << 8) | buf[5]);
    raw->gyro[0]  = (int16_t)(((uint16_t)buf[8]  << 8) | buf[9]);
    raw->gyro[1]  = (int16_t)(((uint16_t)buf[10] << 8) | buf[11]);
    raw->gyro[2]  = (int16_t)(((uint16_t)buf[12] << 8) | buf[13]);

    MPU6050_Convert(raw);
    return 0;
}

void MPU6050_Convert(MPU6050_RawData_t *raw)
{
    for (uint8_t i = 0; i < 3; i++)
    {
        raw->accel_g[i]  = (float)raw->accel[i] / s_accelSens;
        raw->gyro_dps[i] = (float)raw->gyro[i]  / s_gyroSens;
    }
}
