/* 芯片坐标系到机体坐标系的映射矩阵（默认单位阵，按实际安装方向修改） */
static signed char s_gyroOrientation[9] = { 1, 0, 0,
                                            0, 1, 0,
                                            0, 0, 1 };

static unsigned short inv_row_2_scale(const signed char *row)
{
    unsigned short b;

    if (row[0] > 0)      b = 0;
    else if (row[0] < 0) b = 4;
    else if (row[1] > 0) b = 1;
    else if (row[1] < 0) b = 5;
    else if (row[2] > 0) b = 2;
    else if (row[2] < 0) b = 6;
    else                 b = 7;      /* 该轴不参与姿态解算 */

    return b;
}

static unsigned short inv_orientation_matrix_to_scalar(const signed char *mtx)
{
    unsigned short scalar;

    scalar = inv_row_2_scale(mtx);
    scalar |= inv_row_2_scale(mtx + 3) << 3;
    scalar |= inv_row_2_scale(mtx + 6) << 6;

    return scalar;
}

/* 自检（可选）：DMP 自带标定，摆正模块后运行一次更准 */
static void run_self_test(void)
{
    int       result;
    long      gyro[3], accel[3];
    /* 0 表示自检失败但继续运行；需要严格调试时把返回值打印出来 */
    result = mpu_run_self_test(gyro, accel);
    if (result == 0x7)
    {
        float sens;
        unsigned short accel_sens;

        mpu_get_gyro_sens(&sens);
        gyro[0] = (long)(gyro[0] * sens);
        gyro[1] = (long)(gyro[1] * sens);
        gyro[2] = (long)(gyro[2] * sens);
        dmp_set_gyro_bias(gyro);

        mpu_get_accel_sens(&accel_sens);
        accel[0] *= accel_sens;
        accel[1] *= accel_sens;
        accel[2] *= accel_sens;
        dmp_set_accel_bias(accel);
    }
}

/**
 * @brief  DMP 初始化
 * @retval 0 成功，非 0 为失败步骤编号（方便定位问题）
 */
uint8_t MPU_DMP_Init(void)
{
    /* 1) 基础传感器初始化（软件 IIC + 量程 + 时钟） */
    if (MPU6050_Init() != 0)
    {
        return 1;
    }

    /* 2) DMP 驱动初始化 */
    if (mpu_init(NULL) != 0)
    {
        return 2;
    }

    /* 3) 使能六轴 */
    if (mpu_set_sensors(INV_XYZ_GYRO | INV_XYZ_ACCEL) != 0)
    {
        return 3;
    }

    /* 4) FIFO 中放入六轴数据 */
    if (mpu_configure_fifo(INV_XYZ_GYRO | INV_XYZ_ACCEL) != 0)
    {
        return 4;
    }

    /* 5) 采样率 */
    if (mpu_set_sample_rate(DEFAULT_MPU_HZ) != 0)
    {
        return 5;
    }

    /* 6) 加载 DMP 固件（这一步最耗时，也最容易因 IIC 不稳定失败） */
    if (dmp_load_motion_driver_firmware() != 0)
    {
        return 6;
    }

    /* 7) 设置姿态矩阵方向 */
    if (dmp_set_orientation(inv_orientation_matrix_to_scalar(s_gyroOrientation)) != 0)
    {
        return 7;
    }

    /* 8) 使能功能：六轴低姿态四元数 + 原始数据 + 陀螺标定 */
    if (dmp_enable_feature(DMP_FEATURE_6X_LP_QUAT | DMP_FEATURE_TAP |
                           DMP_FEATURE_ANDROID_ORIENT |
                           DMP_FEATURE_SEND_RAW_ACCEL |
                           DMP_FEATURE_SEND_CAL_GYRO |
                           DMP_FEATURE_GYRO_CAL) != 0)
    {
        return 8;
    }

    /* 9) DMP 输出速率 */
    if (dmp_set_fifo_rate(DEFAULT_MPU_HZ) != 0)
    {
        return 9;
    }

    /* 10) 可选自检（模块必须水平静止放置） */
    run_self_test();

    /* 11) 启动 DMP */
    if (mpu_set_dmp_state(1) != 0)
    {
        return 10;
    }

    return 0;
}

