#include <string.h>

#include "vofa.h"
#include "FreeRTOS.h"
#include "semphr.h"

static SemaphoreHandle_t s_txMutex = NULL;
static uint8_t           s_txBuf[VOFA_TX_BUF_SIZE];

void VOFA_Init(void)
{
    s_txMutex = xSemaphoreCreateMutex();
    configASSERT(s_txMutex != NULL);
}

static void VOFA_SendString(char *str, uint16_t len)
{
    if (s_txMutex == NULL)
    {
        return;
    }

    xSemaphoreTake(s_txMutex, portMAX_DELAY);

    /* 等待上一次 DMA 发送结束 */
    while (huart1.gState != HAL_UART_STATE_READY)
    {
        vTaskDelay(1);
    }

    if (len > VOFA_TX_BUF_SIZE)
    {
        len = VOFA_TX_BUF_SIZE;
    }
    memcpy(s_txBuf, str, len);

    HAL_UART_Transmit_DMA(&huart1, s_txBuf, len);

    xSemaphoreGive(s_txMutex);
}

/* JustPrint："ch0,ch1,ch2,...\n" */
void VOFA_SendChannels(const float *ch, uint8_t num)
{
    char    buf[VOFA_TX_BUF_SIZE];
    int     pos = 0;
    int     n;

    if ((ch == NULL) || (num == 0U))
    {
        return;
    }

    for (uint8_t i = 0; i < num; i++)
    {
        n = snprintf(&buf[pos], (size_t)(VOFA_TX_BUF_SIZE - (uint16_t)pos),
                     (i == (num - 1U)) ? "%.3f" : "%.3f,", ch[i]);
        if ((n <= 0) || (n >= (VOFA_TX_BUF_SIZE - pos)))
        {
            return;
        }
        pos += n;
    }

    n = snprintf(&buf[pos], (size_t)(VOFA_TX_BUF_SIZE - (uint16_t)pos), "\n");
    if (n <= 0)
    {
        return;
    }
    pos += n;

    VOFA_SendString(buf, (uint16_t)pos);
}

/* 只发六条原始曲线：Accel XYZ + Gyro XYZ */
void VOFA_SendRaw6(const float *ch)
{
    VOFA_SendChannels(ch, 6);
}

/* 只发三条角度曲线：Pitch Roll Yaw */
void VOFA_SendAngle3(const float *ch)
{
    VOFA_SendChannels(ch, 3);
}
