/* ============================================================================
 * 任务二 框架设计（采样 / 打印解耦）
 *
 *   Task_MpuSample  : 5 ms 绝对周期（vTaskDelayUntil），读取原始数据 + DMP 角度，
 *                     打包后投入消息队列（生产者）
 *   Task_VofaPrint  : 阻塞等待消息队列，取到后通过串口 DMA 发给 VOFA（消费者）
 *
 * 好处：采样周期严格 5 ms 不受串口发送耗时影响；打印失败/变慢不会拖垮采样。
 * ==========================================================================*/

static TaskHandle_t   s_taskSample = NULL;
static TaskHandle_t   s_taskPrint  = NULL;
static QueueHandle_t  s_mpuQueue   = NULL;

/* ---------------------- 任务一：MPU6050 5 ms 定周期采样 ---------------------- */
static void Task_MpuSample(void *argument)
{
    TickType_t   lastWakeTime;
    const TickType_t periodTicks = pdMS_TO_TICKS(MPU_SAMPLE_PERIOD_MS);
    MPU6050_RawData_t raw;
    MpuSample_t       sample;
    uint8_t           dmpReady = 0;

    /* 初始化：软件 IIC + MPU6050 + DMP */
    if (MPU_DMP_Init() == 0)
    {
        dmpReady = 1;
    }
    /* dmpReady == 0 时仍继续输出六轴原始数据，方便排查 DMP 加载失败的问题 */

    lastWakeTime = xTaskGetTickCount();

    for (;;)
    {
        memset(&sample, 0, sizeof(sample));

        /* 1) 原始数据（三轴加速度 + 三轴陀螺仪） */
        if (MPU6050_ReadRaw(&raw) == 0)
        {
            memcpy(sample.accel,     raw.accel,     sizeof(sample.accel));
            memcpy(sample.gyro,      raw.gyro,      sizeof(sample.gyro));
            memcpy(sample.accel_g,   raw.accel_g,   sizeof(sample.accel_g));
            memcpy(sample.gyro_dps,  raw.gyro_dps,  sizeof(sample.gyro_dps));
        }

        /* 2) DMP 解算角度 */
        if (dmpReady)
        {
            (void)MPU_DMP_GetAngles(&sample.pitch, &sample.roll, &sample.yaw);
        }

        sample.tick = (uint32_t)xTaskGetTickCount();

        /* 3) 投送给打印任务 */
        (void)xQueueSend(s_mpuQueue, &sample, 0);

        /* 4) 绝对周期 5 ms */
        vTaskDelayUntil(&lastWakeTime, periodTicks);
    }
}

/* -------------------------- 任务二：VOFA 打印 -------------------------- */
static void Task_VofaPrint(void *argument)
{
    MpuSample_t sample;
    float       ch[9];

    for (;;)
    {
        if (xQueueReceive(s_mpuQueue, &sample, portMAX_DELAY) == pdPASS)
        {
            /* 前 6 条：三轴加速度(g) + 三轴陀螺仪(°/s) */
            ch[0] = sample.accel_g[0];
            ch[1] = sample.accel_g[1];
            ch[2] = sample.accel_g[2];
            ch[3] = sample.gyro_dps[0];
            ch[4] = sample.gyro_dps[1];
            ch[5] = sample.gyro_dps[2];

            /* 后 3 条：DMP 解算的 Pitch / Roll / Yaw（°） */
            ch[6] = sample.pitch;
            ch[7] = sample.roll;
            ch[8] = sample.yaw;

            /* JustPrint 协议：一行 9 个通道，5 ms 一帧，VOFA 打开时间戳显示 */
            VOFA_SendChannels(ch, 9);
        }
    }
}

/* ------------------------------- 任务创建 ------------------------------- */
void App_Tasks_Create(void)
{
    VOFA_Init();

    s_mpuQueue = xQueueCreate(MPU_QUEUE_LENGTH, sizeof(MpuSample_t));
    configASSERT(s_mpuQueue != NULL);

    xTaskCreate(Task_MpuSample,
                "MpuSample",
                TASK_MPU_STACK,
                NULL,
                TASK_MPU_PRIO,
                &s_taskSample);

    xTaskCreate(Task_VofaPrint,
                "VofaPrint",
                TASK_PRINT_STACK,
                NULL,
                TASK_PRINT_PRIO,
                &s_taskPrint);
}
