/* USER CODE BEGIN Includes */
#include <stdio.h>
/* USER CODE END Includes */

/* USER CODE BEGIN 0 */
extern UART_HandleTypeDef huart1;   // 通常由 usart.h 提供

int fputc(int ch, FILE *f)
{
    HAL_UART_Transmit(&huart1, (uint8_t *)&ch, 1, 1000);
    return ch;
}
/* USER CODE END 0 */

int main(void) {
  ...
  /* USER CODE BEGIN 2 */
  CAN_TxHeaderTypeDef txHeader;
  uint8_t  txData[8];
  uint32_t txMailbox;
  uint16_t periods[3] = {2000, 1000, 400};   // 依次切换的呼吸周期(ms)
  uint8_t idx = 0;
  uint32_t seq = 0;

  HAL_CAN_Start(&hcan);

  txHeader.StdId = 0x123;
  txHeader.ExtId = 0x00;
  txHeader.IDE   = CAN_ID_STD;
  txHeader.RTR   = CAN_RTR_DATA;
  txHeader.DLC   = 8;
  txHeader.TransmitGlobalTime = DISABLE;

  printf("CAN sender (F103) start, 500kbps\r\n");
  /* USER CODE END 2 */

  while (1) {
    /* USER CODE BEGIN 3 */
    uint16_t period = periods[idx];
    txData[0] = 0xAA;
    txData[1] = 0x01;                      // CMD: 设置呼吸周期
    txData[2] = (uint8_t)(period >> 8);
    txData[3] = (uint8_t)(period & 0xFF);
    txData[4] = (uint8_t)(txData[1] + txData[2] + txData[3]);
    txData[5] = 0x00;
    txData[6] = 0x00;
    txData[7] = 0x55;

    HAL_StatusTypeDef st = HAL_CAN_AddTxMessage(&hcan, &txHeader, txData, &txMailbox);
    if (st == HAL_OK) {
      printf("[%lu] TX ok: breath period = %u ms\r\n", ++seq, period);
    } else {
      printf("[%lu] TX FAIL (err=%d) - check bus: 2 nodes? 120R x2? common GND?\r\n", ++seq, st);
    }

    /* 每 500ms 发一帧；每 10 帧换一个周期（5 秒换一次），方便观察呼吸灯频率变化 */
    if ((seq % 10) == 0) {
      idx = (idx + 1) % 3;
    }
    HAL_Delay(500);
    /* USER CODE END 3 */
  }
}
