  */
int main(void)
{
  /* USER CODE BEGIN 1 */

  /* USER CODE END 1 */

  /* MCU Configuration--------------------------------------------------------*/

  /* Reset of all peripherals, Initializes the Flash interface and the Systick. */
  HAL_Init();

  /* USER CODE BEGIN Init */

  /* USER CODE END Init */

  /* Configure the system clock */
  SystemClock_Config();

  /* USER CODE BEGIN SysInit */

  /* USER CODE END SysInit */

  /* Initialize all configured peripherals */
  MX_GPIO_Init();
  MX_CAN_Init();
  MX_USART1_UART_Init();
  /* USER CODE BEGIN 2 */

  CAN_TxHeaderTypeDef txHeader;
  uint8_t             txData[8];
  uint32_t            txMailbox;
  const uint16_t      periodTable[3] = {2000u, 1000u, 400u};  /* 依次切换的呼吸周期(ms) */
  uint8_t             idx  = 0;
  uint32_t            seq  = 0;

  if (HAL_CAN_Start(&hcan) != HAL_OK)
  {
      printf("CAN start FAILED!\r\n");
      Error_Handler();
  }

  txHeader.StdId              = 0x123;        /* 标准 ID，天空星端不过滤，任意 ID 都收 */
  txHeader.ExtId              = 0x00;
  txHeader.IDE                = CAN_ID_STD;
  txHeader.RTR                = CAN_RTR_DATA;
  txHeader.DLC                = 8;
  txHeader.TransmitGlobalTime = DISABLE;

  printf("\r\n=== CAN sender (F103C8T6) 500kbps ===\r\n");
  printf("Send a frame every 500ms, change period every 5s\r\n");
  /* USER CODE END 2 */

  /* Infinite loop */
  /* USER CODE BEGIN WHILE */
  while (1)
  {
    /* USER CODE END WHILE */

    /* USER CODE BEGIN 3 */
    uint16_t          period;
    HAL_StatusTypeDef st;

    period = periodTable[idx];

    txData[0] = 0xAA;                                  /* 头帧 */
    txData[1] = 0x01;                                  /* CMD: 修改呼吸周期 */
    txData[2] = (uint8_t)(period >> 8);                /* 数据高字节 */
    txData[3] = (uint8_t)(period & 0xFFU);             /* 数据低字节 */
    txData[4] = (uint8_t)(txData[1] + txData[2] + txData[3]);  /* 校验和 */
    txData[5] = 0x00;
    txData[6] = 0x00;
    txData[7] = 0x55;                                  /* 尾帧 */

    st = HAL_CAN_AddTxMessage(&hcan, &txHeader, txData, &txMailbox);

    if (st == HAL_OK)
    {
        printf("[%lu] TX ok  : id=0x123 data=%02X %02X %02X %02X %02X %02X %02X %02X  (breath period = %u ms)\r\n",
               ++seq,
               txData[0], txData[1], txData[2], txData[3],
               txData[4], txData[5], txData[6], txData[7],
               period);
    }
    else
    {
        printf("[%lu] TX FAIL (err=%d) -> check: 2 nodes on bus? 120R x2? common GND? 500k both sides?\r\n",
               ++seq, st);
    }

    /* 每 10 帧（约 5 秒）换一个周期，方便观察天空星呼吸灯频率变化 */
    if ((seq % 10U) == 0U)
    {
        idx = (idx + 1U) % 3U;
    }

    HAL_Delay(500);
  }
  /* USER CODE END 3 */
}

