#include <string.h>
#include "mpu6050.h"
#include "soft_i2c.h"
#include "board_config.h"

/* 底层读写封装：全部走软件 IIC */
int MPU_Write_Len(uint8_t addr, uint8_t reg, uint8_t len, uint8_t *buf)
{
