```c
#include <math.h>
#include "attitude.h"

static float s_pitch = 0, s_roll = 0, s_yaw = 0;

void Attitude_Reset(void) { s_pitch=s_roll=s_yaw=0; }

void Attitude_Update(const int16_t accel[3], const int16_t gyro[3], float dt)
{
    /* 原始值转物理单位 */
    float ax = (float)accel[0] / 16384.0f;
    float ay = (float)accel[1] / 16384.0f;
    float az = (float)accel[2] / 16384.0f;
    float gx = (float)gyro[0]  / 131.0f;    /* °/s */
    float gy = (float)gyro[1]  / 131.0f;
    float gz = (float)gyro[2]  / 131.0f;

    /* 1) 陀螺积分（快、无噪声，但漂移） */
    s_pitch += gx * dt;
    s_roll  += gy * dt;
    s_yaw   += gz * dt;

    /* 2) 加速度计算姿态角（慢、有噪声，但长期不漂） */
    float pitchAcc = atan2f(-ax, sqrtf(ay*ay + az*az)) * 57.29578f;
    float rollAcc  = atan2f(ay, az) * 57.29578f;

    /* 3) 互补滤波：98% 陀螺 + 2% 加速度（0.02*0.005=100ms 时间常数级）*/
    /*    加速度只在非高动态时可信：模长接近 1g 才用（晃动尖峰不污染姿态） */
    float amag = sqrtf(ax*ax+ay*ay+az*az);
    if (amag > 0.6f && amag < 1.6f) {
        s_pitch = 0.98f * s_pitch + 0.02f * pitchAcc;
        s_roll  = 0.98f * s_roll  + 0.02f * rollAcc;
    }
    /* yaw 无磁力计，只能积分（会缓慢漂移——如实说明） */
}

float Attitude_GetPitch(void) { return s_pitch; }
float Attitude_GetRoll(void)  { return s_roll; }
float Attitude_GetYaw(void)   { return s_yaw; }
```

