     * 优先级必须 >= 5（FreeRTOS 中可在 ISR 里调用 FromISR API 的最低优先级），
     * 本项目 NVIC_PRIORITYGROUP_4，数值越大优先级越低。 */
    HAL_NVIC_SetPriority(CAN1_RX0_IRQn, 5, 0);
    HAL_NVIC_EnableIRQ(CAN1_RX0_IRQn);
}
