static void Task_MotorCtrl(void *arg)
{
    TickType_t lastWake = xTaskGetTickCount();
    CanRxPacket_t pkt;
    for (;;)
    {
        vTaskDelayUntil(&lastWake, pdMS_TO_TICKS(CTRL_TASK_PERIOD_MS));

        while (CAN_GetQueue() && xQueueReceive(CAN_GetQueue(), &pkt, 0) == pdPASS)
        {
            if (pkt.id == MOTOR_FEEDBACK_ID) GM6020_Update(&g_motor, pkt.data);
        }

        if (!GM6020_IsOnline(&g_motor, MOTOR_RX_TIMEOUT_MS))
        {
            g_ctrl.out = 0;
            PID_Reset(&g_ctrl.pidSpeed); PID_Reset(&g_ctrl.pidAngle);
            GM6020_SendStop(MOTOR_ID);
            continue;
        }

        float out = 0;
        switch (g_ctrl.mode) {
          case MODE_VOLT: out = g_ctrl.voltCmd; break;
          case MODE_SPEED: out = PID_Calc(&g_ctrl.pidSpeed, g_ctrl.speedTarget, g_motor.speed); break;
          case MODE_ANGLE: {
              float sp = PID_Calc(&g_ctrl.pidAngle, g_ctrl.angleTarget, g_motor.angleCont);
              clamp ±speedLimit
              g_ctrl.speedCmdDbg = sp;
              out = PID_Calc(&g_ctrl.pidSpeed, sp, g_motor.speed);
              break; }
          default: out = 0; break;
        }
        clamp ±voltLimit
        g_ctrl.out = out;
        GM6020_SendVoltage(MOTOR_ID, out);
    }
}
