#ifndef __RC_IBUS_H
#define __RC_IBUS_H

#include <stdint.h>

typedef struct
{
    uint16_t ch[16];        /* iBus 1000~2000us；DBUS 364~1684（中位 1024） */
    uint8_t  s1;            /* DBUS 拨杆（iBus 模式下无效） */
    uint8_t  s2;
    uint8_t  linked;
    uint32_t frameCount;
    uint32_t lastFrameMs;
} RC_t;

extern RC_t g_rc;

void    MX_RC_UART_Init(void);
